function txRow(t,actions=false){const color=t.kind==="Income"?"positive":t.kind==="Expense"?"negative":"";return `<div class="list-row transaction-row" data-open-tx="${esc(t.id)}"><div class="row-icon ${t.kind==="Income"?"income-icon":t.kind==="Expense"?"expense-icon":""}">${t.kind==="Income"?"↙":t.kind==="Expense"?"↗":"⇄"}</div><div class="row-main"><strong>${esc(t.category)}</strong><small>${esc(t.note||t.kind)}${t.account?" · "+esc(t.account):""}${t.recurring?" · Recurring":""}</small></div><div class="row-amount ${color}">${t.kind==="Income"?"+":t.kind==="Expense"?"−":""}${money(t.amount)}</div>${actions?`<label class="tx-select"><input type="checkbox" data-select-tx="${esc(t.id)}" ${selectedTransactionIds.has(String(t.id))?"checked":""} aria-label="Select transaction"></label>`:""}</div>`;}

