function renderBudgets(){const month=$("budgetMonth").value||monthKey();$("budgetList").className="budget-stack"+(state.budgets.length?"":" empty");$("budgetList").innerHTML=state.budgets.length?state.budgets.map(b=>{const spent=sum(state.transactions.filter(t=>t.kind==="Expense"&&t.category===b.category&&inMonth(t.date,month)),t=>t.amount),pct=b.limit?spent/b.limit*100:0;return `<div class="budget-item"><div class="budget-head"><button type="button" class="text-btn" data-budget-category="${esc(b.category)}">${esc(b.category)}</button><span>${money(spent)} <small>/ ${money(b.limit)}</small></span></div><div class="progress"><span class="${pct>100?"over":""}" style="width:${Math.min(100,pct)}%"></span></div><div class="budget-foot"><span>${Math.round(pct)}% used</span><button class="text-btn" data-budget-delete="${b.id}">Remove</button></div></div>`;}).join(""):empty("No budgets set yet.");document.querySelectorAll("[data-budget-delete]").forEach(b=>b.onclick=async()=>{state.budgets=state.budgets.filter(x=>x.id!==b.dataset.budgetDelete);await persist();});}
