pendingBluecoins=null;
$("bluecoinsInput").onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const data=JSON.parse(await file.text());if(data.format!=="mywealth-bluecoins-import-v1"||!Array.isArray(data.transactions)||!Array.isArray(data.accounts))throw Error("This is not a supported My Wealth export.");pendingBluecoins=data;$("bluecoinsPreview").textContent=`Ready to import ${data.transactions.length.toLocaleString("en-IN")} records, ${data.accounts.length} accounts, ${data.categories?.parents?.length||0} parent categories and ${data.categories?.children?.length||0} subcategories. Amount scale will be validated and normalized before saving.`;$("confirmBluecoinsBtn").disabled=false;}catch(err){pendingBluecoins=null;$("bluecoinsPreview").textContent="Could not read file: "+err.message;$("confirmBluecoinsBtn").disabled=true;}e.target.value="";};
$("confirmBluecoinsBtn").onclick=async()=>{if(!pendingBluecoins)return;const preview=pendingBluecoins.transactions.filter(t=>!t.isReminder);const sample=preview.find(t=>t.source?.amount!==undefined&&Number(t.source.amount)!==0);const ratio=sample?Math.abs(Number(sample.amount)/Number(sample.source.amount)):0;if(!ratio||!(Math.abs(ratio-0.01)<0.000001||Math.abs(ratio-1/1000000)<0.000000001)) {toast("Amount scale could not be validated. Import stopped.");return;}if(!confirm(`Import ${pendingBluecoins.transactions.length} source records and ${pendingBluecoins.accounts.length} account records? Amount conversion validated. This adds the full history.`))return;
 const batch="bluecoins-"+id(), existing=new Set(state.transactions.map(t=>String(t.sourceId||""))),accountMap={};
 for(const a of pendingBluecoins.accounts){if(a.accountsTableID<2)continue;let existingAcc=state.accounts.find(x=>String(x.sourceId)===String(a.accountsTableID));if(!existingAcc){existingAcc={id:id(),sourceId:String(a.accountsTableID),name:a.accountName,type:a.accountTypeID===3?"Bank":a.accountTypeID===4?"Credit card":a.accountTypeID===5?"Investment":"Other",openingBalance:0,closed:!!a.accountHidden,source:"Bluecoins",sourceBatch:batch};state.accounts.push(existingAcc);}accountMap[String(a.accountsTableID)]=existingAcc.id;}
 let added=0;const sourceRows=pendingBluecoins.transactions;const batchSize=200;
 // Commit in small durable batches. If Safari closes mid-import, already committed
 // rows remain in IndexedDB and a retry skips them by sourceId.
 for(let offset=0;offset<sourceRows.length;offset+=batchSize){
   const chunk=sourceRows.slice(offset,offset+batchSize);
   for(const t of chunk){const sid=String(t.sourceId??"");if(sid&&existing.has(sid))continue;const sourceAmount=Number(t.source?.amount??t.amount)||0;const amount=Math.abs(sourceAmount/1000000);const kind=t.type==="Transfer"?"Transfer":t.type==="Income"?"Income":"Expense";state.transactions.push({id:id(),sourceId:sid,date:String(t.date||"").slice(0,10),amount,kind,category:t.category||"Uncategorised",parentCategory:t.parentCategory||"",note:[t.description,t.notes].filter(Boolean).join(" · "),accountId:accountMap[String(t.accountId)]||null,account:t.account||"",counterAccountId:accountMap[String(t.counterAccountId)]||null,counterAccount:t.counterAccount||"",transferGroupId:t.transferGroupId||0,labels:t.labels||[],isReminder:!!t.isReminder,deletedFlag:t.deletedFlag,sourceAmountRaw:sourceAmount,sourceBatch:batch,source:"Bluecoins",amountScaleCorrected:true});if(sid)existing.add(sid);added++;}
   if(!Array.isArray(state.categories))state.categories=[];
   const importedNames=[...new Set(sourceRows.filter(x=>!x.isReminder&&x.category).map(x=>x.category))];
   for(const name of importedNames){const inferredKind=sourceRows.find(x=>x.category===name&&x.type==="Income")?"Income":"Expense";if(!state.categories.some(c=>c.name===name&&c.kind===inferredKind))state.categories.push({kind:inferredKind,name,source:"Bluecoins"});}
   state.bluecoinsMeta={categoryTree:pendingBluecoins.categories,source:pendingBluecoins.source,sourceBatch:batch,importedAt:new Date().toISOString(),sourceRecordCount:sourceRows.length,addedRecords:added,reminders:sourceRows.filter(t=>t.isReminder).length,amountScale:"source millionths divided by 1,000,000",progress:Math.min(offset+chunk.length,sourceRows.length)};
   if(!(await persist())){toast(`Import paused after ${added} records were safely saved. Select the same file and retry to continue.`);return;}
   $("bluecoinsPreview").textContent=`Saving Bluecoins history: ${Math.min(offset+chunk.length,sourceRows.length).toLocaleString("en-IN")} / ${sourceRows.length.toLocaleString("en-IN")} records…`;
 }
 state.bluecoinsMeta.completedAt=new Date().toISOString();refreshAdvancedFilters();options($("entryCategory"),getCategories(currentKind),"");options($("budgetCategory"),getCategories("Expense"),"");if(!(await persist()))return;pendingBluecoins=null;$("bluecoinsPreview").textContent=`Imported ${added.toLocaleString("en-IN")} records. Amounts normalized to INR; account links retained.`;$("confirmBluecoinsBtn").disabled=true;toast(`Imported ${added.toLocaleString("en-IN")} Bluecoins records`);};

function getCategories(kind){
 const base=kind==="Income"?INCOMES:EXPENSES;
 const raw=state.categories;
 // Bluecoins migration stores category metadata as {parents:[], children:[]};
 // user-managed categories use an array. Never call .filter on the object shape.
 const rows=Array.isArray(raw)?raw:[];
 const hidden=new Set(rows.filter(c=>c.kind===kind&&(c.deleted||c.oldName)).map(c=>c.oldName||c.name));
 const renamed=rows.filter(c=>c.kind===kind&&c.oldName&&!c.deleted).map(c=>c.name);
 const custom=rows.filter(c=>c.kind===kind&&!c.deleted&&!c.oldName).map(c=>c.name);
 const imported=(state.transactions||[]).filter(t=>t.kind===kind&&t.category&&!t.isReminder).map(t=>t.category);
 return [...new Set([...base.filter(n=>!hidden.has(n)),...renamed,...custom,...imported])].filter(Boolean).sort((a,b)=>a.localeCompare(b));
}
$("manageCategoriesBtn").onclick=()=>{renderCategoryManager();showDialog("categoryDialog");};
function renderCategoryManager(){if(!Array.isArray(state.categories))state.categories=[];const kind=$("categoryKind").value;$("categoryListEditor").innerHTML=[...getCategories(kind)].map(n=>`<div class="category-edit-row"><span>${esc(n)}</span><button type="button" class="text-btn" data-category-edit="${esc(n)}">Rename</button><button type="button" class="text-btn" data-category-delete="${esc(n)}">Delete</button></div>`).join("");document.querySelectorAll("[data-category-edit]").forEach(b=>b.onclick=async()=>{const old=b.dataset.categoryEdit,n=prompt("New category name",old);if(!n||!n.trim())return;const c=state.categories.find(x=>x.kind===kind&&x.name===old);if(c)c.name=n.trim();else state.categories.push({kind,name:n.trim(),oldName:old});state.transactions.forEach(t=>{if(t.kind===kind&&t.category===old)t.category=n.trim();});await persist();renderCategoryManager();});document.querySelectorAll("[data-category-delete]").forEach(b=>b.onclick=async()=>{const name=b.dataset.categoryDelete;if(!confirm(`Remove ${name} from category choices? Existing transactions will keep this category.`))return;state.categories.push({kind,name,deleted:true});await persist();renderCategoryManager();});}
$("categoryKind").onchange=renderCategoryManager;
$("categoryForm").onsubmit=async e=>{e.preventDefault();const kind=$("categoryKind").value,name=$("categoryName").value.trim();if(!name)return;if(getCategories(kind).some(x=>x.toLowerCase()===name.toLowerCase())){toast("Category already exists");return;}state.categories.push({kind,name});if(!(await persist()))return;$("categoryName").value="";renderCategoryManager();toast("Category added");};


function openTransactionDetail(txid){const t=state.transactions.find(x=>String(x.id)===String(txid));if(!t)return;activeDetailTransactionId=t.id;$("detailTitle").textContent=t.category||t.kind;$("transactionDetailBody").innerHTML=`<div class="detail-grid"><p><small>Date</small><strong>${esc(t.date||"—")}</strong></p><p><small>Amount</small><strong>${money(t.amount)}</strong></p><p><small>Type</small><strong>${esc(t.kind)}</strong></p><p><small>Account</small><strong>${esc(t.account||"Unassigned")}</strong></p><p><small>Category</small><strong>${esc(t.category||"—")}</strong></p><p><small>Description</small><strong>${esc(t.note||"—")}</strong></p></div>`;showDialog("transactionDetailDialog");}
function editOrCopyTransaction(copy=false){const t=state.transactions.find(x=>String(x.id)===String(activeDetailTransactionId));if(!t)return;editingTransactionId=copy?null:t.id;currentKind=t.kind==="Income"?"Income":"Expense";$("entryTitle").textContent=copy?"Copy transaction":"Edit transaction";$("saveEntryBtn").textContent=copy?"Save copy":"Save changes";$("transactionForm").reset();$("entryAmount").value=t.amount;$("entryDate").value=copy?new Date().toISOString().slice(0,10):t.date;options($("entryCategory"),getCategories(currentKind),t.category);$("entryNote").value=t.note||"";refreshAccountSelect();$("entryAccount").value=t.accountId||"";$("entryRecurring").checked=!!t.recurring;document.querySelectorAll("[data-kind]").forEach(x=>x.classList.toggle("selected",x.dataset.kind===currentKind));$("transactionDetailDialog").close();showDialog("entryDialog");}
$("detailEditBtn").onclick=()=>editOrCopyTransaction(false);$("detailCopyBtn").onclick=()=>editOrCopyTransaction(true);$("detailDeleteBtn").onclick=async()=>{if(!activeDetailTransactionId||!confirm("Delete this transaction?"))return;state.transactions=state.transactions.filter(t=>String(t.id)!==String(activeDetailTransactionId));$("transactionDetailDialog").close();await persist();toast("Transaction deleted");};
function updateBulkToolbar(){const n=selectedTransactionIds.size;$("selectedTxCount").textContent=`${n} selected`;$("bulkToolbar").classList.toggle("has-selection",n>0);if($("selectAllTx"))$("selectAllTx").checked=n>0&&n===$$("[data-select-tx]").length;}
function $$(sel){return [...document.querySelectorAll(sel)];}
$("selectAllTx").onchange=()=>{$$("[data-select-tx]").forEach(c=>{c.checked=$("selectAllTx").checked;const k=String(c.dataset.selectTx);c.checked?selectedTransactionIds.add(k):selectedTransactionIds.delete(k);});updateBulkToolbar();};
$("bulkDeleteBtn").onclick=async()=>{if(!selectedTransactionIds.size)return;if(!confirm(`Delete ${selectedTransactionIds.size} selected transactions?`))return;state.transactions=state.transactions.filter(t=>!selectedTransactionIds.has(String(t.id)));selectedTransactionIds.clear();await persist();toast("Selected transactions deleted");};
function openBudgetCategory(category,kind="Expense"){const month=$("budgetMonth").value||monthKey();const rows=state.transactions.filter(t=>t.kind===kind&&t.category===category&&inMonth(t.date,month)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));$("budgetTransactionsTitle").textContent=`${category} · ${kind} · ${month}`;$("budgetTransactionsList").innerHTML=rows.length?rows.map(t=>txRow(t,false)).join(""):empty("No transactions for this category and month.");showDialog("budgetTransactionsDialog");}
document.addEventListener("click",e=>{const b=e.target.closest("[data-budget-category]");if(b)openBudgetCategory(b.dataset.budgetCategory,"Expense");const i=e.target.closest("[data-income-category]");if(i)openBudgetCategory(i.dataset.incomeCategory,"Income");});

render();
storageReady.then(()=>{refreshAdvancedFilters();render();}).catch(()=>{});

function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
// One-time automatic correction for legacy imports that were saved 10,000x too high.
(async function repairLegacyBluecoinsAmounts(){const legacy=state.transactions.filter(t=>t.source==="Bluecoins"&&t.sourceAmountRaw!==undefined&&!t.amountScaleCorrected);if(legacy.length){legacy.forEach(t=>{t.amount=Number(t.amount)/10000;t.amountScaleCorrected=true;});if(state.bluecoinsMeta)state.bluecoinsMeta.amountScaleCorrectedAt=new Date().toISOString();await persist();}})();

$("exportCsvBtn").onclick=()=>{const rows=[["date","description","amount","type","category"],...state.transactions.filter(t=>!t.isReminder).map(t=>[t.date,t.note,t.kind==="Income"?t.amount:-t.amount,t.kind,t.category])];download("my-wealth-transactions.csv",rows.map(r=>r.map(csvCell).join(",")).join("\r\n"),"text/csv");};
function csvCell(v){return `"${String(v??"").replace(/"/g,'""')}"`;}
$("exportJsonBtn").onclick=()=>download("my-wealth-backup.json",JSON.stringify(state,null,2),"application/json");
$("restoreJsonInput").onchange=async e=>{try{const obj=JSON.parse(await e.target.files[0].text());if(!obj||!Array.isArray(obj.transactions)||!Array.isArray(obj.assets)||!Array.isArray(obj.liabilities)||!Array.isArray(obj.budgets))throw Error("Invalid backup structure");if(!confirm("Replace all current local data with this backup?"))return;state=obj;if(!(await persist()))throw Error("Could not save restored backup");toast("Backup restored");}catch(err){toast("Restore failed: "+err.message);}e.target.value="";};
$("importCsvInput").onchange=async e=>{try{const text=await e.target.files[0].text(),lines=parseCSV(text);if(lines.length<2)throw Error("No data rows found");const headers=lines[0].map(x=>x.trim().toLowerCase());const idx=k=>headers.indexOf(k);if(["date","amount","type"].some(k=>idx(k)<0))throw Error("CSV needs date, amount and type columns");let count=0;for(const row of lines.slice(1)){const amount=Number(row[idx("amount")]);if(!Number.isFinite(amount)||amount===0)continue;const rawType=(row[idx("type")]||"").toLowerCase();const kind=rawType.includes("income")||amount>0?"Income":"Expense";state.transactions.push({id:id(),date:row[idx("date")]||new Date().toISOString().slice(0,10),amount:Math.abs(amount),kind,category:idx("category")>=0&&row[idx("category")]?row[idx("category")]:"Imported",note:idx("description")>=0?row[idx("description")]:"",recurring:false});count++;}if(!(await persist()))throw Error("Could not save imported rows");toast(`Imported ${count} rows`);}catch(err){toast("Import failed: "+err.message);}e.target.value="";};
function parseCSV(text){const rows=[];let row=[],cell="",quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"'){quoted=!quoted;}else if(c===","&&!quoted){row.push(cell);cell="";}else if((c==="\n"||c==="\r")&&!quoted){if(c==="\r"&&text[i+1]==="\n")i++;row.push(cell);if(row.some(x=>x!==""))rows.push(row);row=[];cell="";}else cell+=c;}row.push(cell);if(row.some(x=>x!==""))rows.push(row);return rows;}

function config(){return JSON.parse(localStorage.getItem("mywealth-cloud")||"{}");}
function updateCloudStatus(){const c=config();$("cloudStatus").textContent=c.url&&c.key?(session?.user?.email?`Connected as ${session.user.email}`:"Configured · Sign in to sync"):"Not configured · Local-only mode";}
$("configureCloudBtn").onclick=()=>{const c=config();$("supabaseUrl").value=c.url||"";$("supabaseKey").value=c.key||"";showDialog("cloudDialog");};
$("cloudForm").onsubmit=e=>{e.preventDefault();const url=$("supabaseUrl").value.trim().replace(/\/$/,""),key=$("supabaseKey").value.trim();if(!/^https:\/\/.+\.supabase\.co$/.test(url)){toast("Enter a valid Supabase project URL");return;}localStorage.setItem("mywealth-cloud",JSON.stringify({url,key}));$("cloudDialog").close();initSupabase();updateCloudStatus();toast("Cloud configuration saved");};
async function initSupabase(){const c=config();if(!c.url||!c.key){supabase=null;return;}supabase={url:c.url,key:c.key};const token=localStorage.getItem("mywealth-token");if(token){try{const res=await sbFetch("/auth/v1/user",{method:"GET",token});if(res?.id)session={user:res,access_token:token};else{localStorage.removeItem("mywealth-token");session=null;}}catch{session=null;}}updateCloudStatus();}
async function sbFetch(path,{method="GET",body,token}={}){if(!supabase)throw Error("Configure cloud sync first");const t=token||session?.access_token||supabase.key;const r=await fetch(supabase.url+path,{method,headers:{"apikey":supabase.key,"Authorization":"Bearer "+t,"Content-Type":"application/json","Prefer":"resolution=merge-duplicates,return=minimal"},...(body!==undefined?{body:JSON.stringify(body)}:{})});const text=await r.text();if(!r.ok)throw Error(text||`Cloud error ${r.status}`);return text?JSON.parse(text):null;}
$("loginBtn").onclick=()=>showDialog("authDialog");
$("authForm").onsubmit=async e=>{e.preventDefault();try{const result=await sbFetch("/auth/v1/token?grant_type=password",{method:"POST",body:{email:$("authEmail").value,password:$("authPassword").value}});session={...result,user:result.user};localStorage.setItem("mywealth-token",result.access_token);updateCloudStatus();$("authDialog").close();toast("Signed in");await syncCloud();}catch(err){toast("Sign in failed: "+err.message);}};
$("signupBtn").onclick=async()=>{try{await sbFetch("/auth/v1/signup",{method:"POST",body:{email:$("authEmail").value,password:$("authPassword").value}});toast("Account created. Check email if confirmation is enabled.");}catch(err){toast("Sign-up failed: "+err.message);}};
$("logoutBtn").onclick=()=>{session=null;localStorage.removeItem("mywealth-token");updateCloudStatus();toast("Signed out");};
$("syncNowBtn").onclick=()=>syncCloud();
async function syncCloud(){if(!supabase){toast("Configure cloud sync first");showDialog("cloudDialog");return;}if(!session?.access_token){toast("Sign in to your cloud account first");showDialog("authDialog");return;}try{const rows=await sbFetch("/rest/v1/user_finance?select=data&id=eq."+encodeURIComponent(session.user.id));if(rows?.[0]?.data){state=mergeState(state,rows[0].data);}const payload={id:session.user.id,data:state,updated_at:new Date().toISOString()};await sbFetch("/rest/v1/user_finance?on_conflict=id",{method:"POST",body:payload});await persist();toast("Cloud sync complete");}catch(err){toast("Sync failed: "+err.message);}}
function mergeState(local,cloud){const merged=emptyState();for(const k of Object.keys(merged)){const map=new Map();[...(cloud[k]||[]),...(local[k]||[])].forEach(x=>map.set(x.id,x));merged[k]=[...map.values()];}return merged;}
$("installHelpBtn").onclick=()=>alert("On your iPhone: open this site in Safari → tap Share → Add to Home Screen → Add. Use Safari, not an in-app browser.");
$("clearDataBtn").onclick=async()=>{if(confirm("Permanently delete all local finance records on this device? This does not delete cloud records.")){state=emptyState();if(await persist())toast("Local data deleted");}};
initSupabase();

if("serviceWorker" in navigator && location.protocol.startsWith("http"))navigator.serviceWorker.register("./sw.js").catch(()=>{});
